// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialValue) public {
        // Ensure initialValue is reasonable and not zero to avoid division issues
        initialValue = bound(initialValue, 1e18, 1e27);

        // Set up state: call XBornID() which sets balances[owner] and leaves value at 1000e18
        // We need to manipulate value via the exposed public variable? No, value is public so we read it.
        // But we cannot write directly. We can call getTokens() to change value, but we need a controlled test.
        // Instead, use vm.prank to call getTokens() with a sender that is not blacklisted, then check the rule.

        address user = address(0x1234);
        vm.deal(user, 1 ether);

        // First, we need to ensure totalRemaining > value so that getTokens() does not cap it
        // totalRemaining = totalSupply - totalDistributed = 500000000e18 - 200000000e18 = 300000000e18
        // value = 1000e18 initially, so condition holds.

        // Record value before the call
        uint256 valueBefore = c.value();

        // Call getTokens() via user (who is not blacklisted)
        vm.prank(user);
        c.getTokens();

        // Get value after
        uint256 valueAfter = c.value();

        // The general rule: after calling getTokens(), the new value must be strictly less than the old value,
        // because in the reference version it gets multiplied by 99999/100000, but in the buggy version it stays the same.
        assertTrue(valueAfter < valueBefore, "value should decrease after getTokens()");
    }
}

