import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testFuzz_property(uint256 initialValue) public {
        initialValue = bound(initialValue, 1e18, 1e27);


        address user = address(0x1234);
        vm.deal(user, 1 ether);


        uint256 valueBefore = c.value();

        vm.prank(user);
        c.getTokens();

        uint256 valueAfter = c.value();

        assertTrue(valueAfter < valueBefore, "value should decrease after getTokens()");
    }
